// Generated by Selenium IDE
import { Builder, By, Key, until } from 'selenium-webdriver';
import assert from 'assert';

describe('Login Suite', function() {
  this.timeout(30000)
  let driver
  let vars
  beforeEach(async function() {
    driver = await new Builder().forBrowser('firefox').build()
    vars = {}
  })
  afterEach(async function() {
    await driver.quit();
  })
  it('email_only', async function() {
    await driver.get("http://localhost:5173/login")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Email")).click()
    vars["admin@test.com"] = await driver.findElement(By.id("Email")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('password_only', async function() {
    await driver.get("http://localhost:5173/login")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Password")).click()
    vars["koshiASWER"] = await driver.findElement(By.id("Password")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
    await driver.findElement(By.css(".pt-4")).click()
    assert(await driver.findElement(By.css(".text-sm\\/tight")).getText() == "Enter a valid Email!")
  })
  it('correct_credentials', async function() {
    await driver.get("http://localhost:5173/login")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Email")).click()
    vars["admin@test.com"] = await driver.findElement(By.id("Email")).getAttribute("value")
    await driver.findElement(By.id("Password")).click()
    vars["Admin123@"] = await driver.findElement(By.id("Password")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
    assert(await driver.getTitle() == "Kannangara Hardwares")
  })
  it('correct_email_and_incorrect_password', async function() {
    await driver.get("http://localhost:5173/login")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Email")).click()
    vars["admin@test.com"] = await driver.findElement(By.id("Email")).getAttribute("value")
    await driver.findElement(By.id("Password")).click()
    vars["kkosgjdfhjd"] = await driver.findElement(By.id("Password")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('invalid_email_and_correct_pw', async function() {
    await driver.get("http://localhost:5173/login")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Email")).click()
    vars["john@deo.com"] = await driver.findElement(By.id("Email")).getAttribute("value")
    await driver.findElement(By.id("Password")).click()
    vars["koshiLA123@"] = await driver.findElement(By.id("Password")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
})
